package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Replacement for System.Numerics.Vector&lt;T&gt; (generated by CSharpToJava converter).
 * A scalar fallback implementation: {@link #getIsHardwareAccelerated()} reports false,
 * so SIMD code paths are skipped at runtime, but the API surface compiles.
 */
public final class Vector<T> {
    private static final int COUNT = 16;

    private final T[] elements;

    /** Mirrors new Vector&lt;T&gt;(value) — every element seeded with the same value. */
    public Vector(T value) {
        @SuppressWarnings("unchecked")
        T[] arr = (T[]) new Object[COUNT];
        Arrays.fill(arr, value);
        this.elements = arr;
    }

    public Vector(T[] data) {
        this.elements = Arrays.copyOf(data, COUNT);
    }

    /** Mirrors Vector&lt;byte&gt;.Count — element count of the widest byte vector. */
    public static int getCount() {
        return COUNT;
    }

    /** Mirrors Vector.IsHardwareAccelerated — always false in the scalar fallback. */
    public static boolean getIsHardwareAccelerated() {
        return false;
    }

    /** Mirrors Vector&lt;T&gt;.Zero. */
    public static <T> Vector<T> getZero() {
        @SuppressWarnings("unchecked")
        T[] arr = (T[]) new Object[COUNT];
        return new Vector<>(arr);
    }

    /** Mirrors Vector.BitwiseOr. */
    public static <T> Vector<T> bitwiseOr(Vector<T> left, Vector<T> right) {
        @SuppressWarnings("unchecked")
        T[] arr = (T[]) new Object[COUNT];
        for (int i = 0; i < COUNT; i++) {
            arr[i] = (T) Integer.valueOf(
                ((Number) left.elements[i]).intValue() | ((Number) right.elements[i]).intValue());
        }
        return new Vector<>(arr);
    }

    /** Mirrors Vector.Equals — 1 in matching lanes, 0 otherwise. */
    public static <T> Vector<T> equals(Vector<T> left, Vector<T> right) {
        @SuppressWarnings("unchecked")
        T[] arr = (T[]) new Object[COUNT];
        for (int i = 0; i < COUNT; i++) {
            arr[i] = (T) Integer.valueOf(
                NumberEquals(left.elements[i], right.elements[i]) ? 1 : 0);
        }
        return new Vector<>(arr);
    }

    /** Mirrors Vector.LessThan — 1 in lanes where left &lt; right, 0 otherwise. */
    public static <T> Vector<T> lessThan(Vector<T> left, Vector<T> right) {
        @SuppressWarnings("unchecked")
        T[] arr = (T[]) new Object[COUNT];
        for (int i = 0; i < COUNT; i++) {
            arr[i] = (T) Integer.valueOf(
                ((Number) left.elements[i]).longValue() < ((Number) right.elements[i]).longValue() ? 1 : 0);
        }
        return new Vector<>(arr);
    }

    /** Mirrors Vector&lt;T&gt;.Equals (instance) — true when every lane matches. */
    public boolean equalsTo(Vector<T> other) {
        return Arrays.equals(elements, other.elements);
    }

    /**
     * Mirrors Vector.AsVectorUInt64 — reinterprets the vector as 64-bit lanes.
     * Each 8 consecutive element values (each holding one byte) form one long lane.
     */
    public static Vector<Long> asVectorUInt64(Vector<?> match) {
        Long[] longs = new Long[COUNT];
        for (int i = 0; i < COUNT; i++) {
            long lane = 0;
            for (int j = 0; j < 8 && i * 8 + j < match.elements.length; j++) {
                long b = ((Number) match.elements[i * 8 + j]).longValue() & 0xFFL;
                lane |= b << (j * 8);
            }
            longs[i] = lane;
        }
        return new Vector<>(longs);
    }

    public T get(int index) {
        return index >= 0 && index < elements.length ? elements[index] : null;
    }

    public int length() {
        return elements.length;
    }

    private static boolean NumberEquals(Object left, Object right) {
        if (left instanceof Number ln && right instanceof Number rn) {
            return ln.longValue() == rn.longValue();
        }
        return left != null && left.equals(right);
    }
}
